package offline;

import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Arrays;

/**
 * Byte-level helpers for the offline receive audit: minimal varint coding, a bounded cursor, an
 * undo journal used for packet transactions, and merged range/byte ledgers.
 *
 * <p>Varints always follow RFC 9000 section 16. Decoding accepts overlong encodings; encoding is
 * always minimal, which is what canonical envelopes require.
 */
final class AuditIo {

    /** Largest value representable by a QUIC varint, and the contract's integer limit. */
    static final long MAX62 = 4611686018427387903L;

    private AuditIo() {}

    /** Signals an unexpectedly short input. Callers translate it into their own error class. */
    static final class Truncated extends RuntimeException {
        Truncated() {}
    }

    /** Growable byte sink that always writes minimal varints. */
    static final class ByteOut {
        private byte[] buf = new byte[32];
        private int n;

        private void ensure(int extra) {
            if (n + extra > buf.length) {
                int cap = Math.max(buf.length * 2, n + extra);
                byte[] grown = new byte[cap];
                System.arraycopy(buf, 0, grown, 0, n);
                buf = grown;
            }
        }

        void u8(int value) {
            ensure(1);
            buf[n++] = (byte) value;
        }

        void bytes(byte[] data) {
            ensure(data.length);
            System.arraycopy(data, 0, buf, n, data.length);
            n += data.length;
        }

        void pn(long value, int width) {
            ensure(width);
            for (int i = width - 1; i >= 0; i--) {
                buf[n + i] = (byte) (value >>> (8 * i));
            }
            n += width;
        }

        void v(long value) {
            if (value < 0 || value > MAX62) {
                throw new IllegalArgumentException("varint out of range: " + value);
            }
            if (value <= 63) {
                u8((int) value);
            } else if (value <= 16383) {
                ensure(2);
                buf[n++] = (byte) (0x40 | (value >>> 8));
                buf[n++] = (byte) value;
            } else if (value <= 1073741823L) {
                ensure(4);
                buf[n++] = (byte) (0x80 | (value >>> 24));
                buf[n++] = (byte) (value >>> 16);
                buf[n++] = (byte) (value >>> 8);
                buf[n++] = (byte) value;
            } else {
                ensure(8);
                buf[n++] = (byte) (0xc0 | (value >>> 56));
                for (int i = 48; i >= 0; i -= 8) {
                    buf[n++] = (byte) (value >>> i);
                }
            }
        }

        int size() {
            return n;
        }

        byte[] toArray() {
            byte[] out = new byte[n];
            System.arraycopy(buf, 0, out, 0, n);
            return out;
        }
    }

    /** Value-equality wrapper for CID bytes. */
    static final class ByteKey {
        private final byte[] bytes;
        private final int hash;

        ByteKey(byte[] bytes) {
            this.bytes = bytes;
            this.hash = Arrays.hashCode(bytes);
        }

        byte[] bytes() {
            return bytes;
        }

        @Override
        public int hashCode() {
            return hash;
        }

        @Override
        public boolean equals(Object other) {
            return other instanceof ByteKey && Arrays.equals(bytes, ((ByteKey) other).bytes);
        }
    }

    /** Forward cursor over a byte range; truncation is reported by {@link Truncated}. */
    static final class Cursor {
        private final byte[] buf;
        private final int end;
        private int pos;

        Cursor(byte[] buf, int pos, int end) {
            this.buf = buf;
            this.pos = pos;
            this.end = end;
        }

        int position() {
            return pos;
        }

        int remaining() {
            return end - pos;
        }

        int u8() {
            if (pos >= end) {
                throw new Truncated();
            }
            return buf[pos++] & 255;
        }

        /** Reads a varint of the width announced by its two top bits, allowing overlong forms. */
        long v() {
            int start = pos;
            if (start >= end) {
                throw new Truncated();
            }
            int first = buf[start] & 255;
            int width = 1 << (first >>> 6);
            if (start + width > end) {
                throw new Truncated();
            }
            long value = first & 0x3f;
            for (int i = 1; i < width; i++) {
                value = (value << 8) | (buf[start + i] & 255);
            }
            pos = start + width;
            return value;
        }

        byte[] bytes(long count) {
            if (count > remaining()) {
                throw new Truncated();
            }
            int taken = (int) count;
            byte[] out = Arrays.copyOfRange(buf, pos, pos + taken);
            pos += taken;
            return out;
        }

        byte[] rest() {
            byte[] out = Arrays.copyOfRange(buf, pos, end);
            pos = end;
            return out;
        }
    }

    /** Records inverse mutations so that a failed packet can be rolled back completely. */
    static final class Journal {
        private ArrayList<Runnable> ops = new ArrayList<>();

        void push(Runnable undo) {
            ops.add(undo);
        }

        void undoAll() {
            for (int i = ops.size() - 1; i >= 0; i--) {
                ops.get(i).run();
            }
            ops.clear();
        }

        void commit() {
            ops.clear();
        }
    }

    /**
     * Sorted union of disjoint half-open intervals with adjacent intervals merged. Bulk merges
     * keep large ACK frames linear in the number of ranges they carry.
     */
    static final class Ranges {
        final ArrayList<long[]> list = new ArrayList<>();

        int size() {
            return list.size();
        }

        boolean isEmpty() {
            return list.isEmpty();
        }

        ArrayList<long[]> intervals() {
            return list;
        }

        long cardinality() {
            long total = 0;
            for (long[] range : list) {
                total += range[1] - range[0];
            }
            return total;
        }

        /** Prefix cardinality from zero, that is the first interval when it starts at zero. */
        long prefix() {
            if (list.isEmpty() || list.get(0)[0] != 0) {
                return 0;
            }
            return list.get(0)[1];
        }

        boolean contains(long value) {
            int lo = 0;
            int hi = list.size();
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                long[] range = list.get(mid);
                if (value < range[0]) {
                    hi = mid;
                } else if (value >= range[1]) {
                    lo = mid + 1;
                } else {
                    return true;
                }
            }
            return false;
        }

        /** Merges ascending, disjoint, non-adjacent intervals into the union. */
        void addAll(long[][] ranges, Journal journal) {
            if (ranges.length == 0) {
                return;
            }
            long firstStart = ranges[0][0];
            long lastEnd = ranges[ranges.length - 1][1];
            int lo = firstAtOrAfter(firstStart);
            int hi = firstAfter(lastEnd);
            long[][] removed = new long[hi - lo][];
            for (int i = lo; i < hi; i++) {
                removed[i - lo] = list.get(i);
            }
            ArrayList<long[]> merged = new ArrayList<>(ranges.length + removed.length);
            int a = lo;
            int b = 0;
            long start = 0;
            long end = 0;
            boolean open = false;
            while (a < hi || b < ranges.length) {
                long[] next;
                if (a < hi && (b >= ranges.length || list.get(a)[0] <= ranges[b][0])) {
                    next = list.get(a++);
                } else {
                    next = ranges[b++];
                }
                if (!open) {
                    start = next[0];
                    end = next[1];
                    open = true;
                } else if (next[0] <= end) {
                    if (next[1] > end) {
                        end = next[1];
                    }
                } else {
                    merged.add(new long[] {start, end});
                    start = next[0];
                    end = next[1];
                }
            }
            if (open) {
                merged.add(new long[] {start, end});
            }
            final int at = lo;
            final int inserted = merged.size();
            final long[][] previous = removed;
            if (inserted != removed.length || true) {
                journal.push(
                        () -> {
                            list.subList(at, at + inserted).clear();
                            if (previous.length > 0) {
                                list.addAll(at, Arrays.asList(previous));
                            }
                        });
            }
            list.subList(lo, hi).clear();
            list.addAll(lo, merged);
        }

        void add(long start, long end, Journal journal) {
            addAll(new long[][] {{start, end}}, journal);
        }

        /** First index whose interval ends at or after value, so adjacency is included. */
        private int firstAtOrAfter(long value) {
            int lo = 0;
            int hi = list.size();
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (list.get(mid)[1] < value) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
            return lo;
        }

        /** First index whose interval starts strictly after value. */
        private int firstAfter(long value) {
            int lo = 0;
            int hi = list.size();
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (list.get(mid)[0] <= value) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
            return lo;
        }
    }

    /** One contiguous run of stored bytes. */
    static final class Segment {
        final long start;
        final long end;
        final byte[] data;

        Segment(long start, long end, byte[] data) {
            this.start = start;
            this.end = end;
            this.data = data;
        }
    }

    /**
     * Sparse reassembly buffer for stream or crypto bytes. Segments stay sorted, disjoint and
     * non-adjacent; equal overlaps are accepted and differing ones are rejected by the caller.
     */
    static final class Ledger {
        final ArrayList<Segment> segments = new ArrayList<>();

        boolean isEmpty() {
            return segments.isEmpty();
        }

        ArrayList<Segment> segments() {
            return segments;
        }

        /**
         * Adds bytes, merging with touching or overlapping segments. Returns false when the new
         * bytes disagree with already stored bytes in the overlap; nothing is mutated then.
         */
        boolean add(long start, byte[] data, Journal journal) {
            if (data.length == 0) {
                return true;
            }
            long end = start + data.length;
            int lo = firstEndingAtOrAfter(start);
            int hi = firstStartingAfter(end);
            for (int i = lo; i < hi; i++) {
                Segment segment = segments.get(i);
                long from = Math.max(segment.start, start);
                long to = Math.min(segment.end, end);
                for (long p = from; p < to; p++) {
                    if (segment.data[(int) (p - segment.start)] != data[(int) (p - start)]) {
                        return false;
                    }
                }
            }
            long mergedStart = lo < hi ? Math.min(start, segments.get(lo).start) : start;
            long mergedEnd = lo < hi ? Math.max(end, segments.get(hi - 1).end) : end;
            byte[] merged = new byte[(int) (mergedEnd - mergedStart)];
            for (int i = lo; i < hi; i++) {
                Segment segment = segments.get(i);
                System.arraycopy(segment.data, 0, merged, (int) (segment.start - mergedStart), segment.data.length);
            }
            System.arraycopy(data, 0, merged, (int) (start - mergedStart), data.length);
            Segment[] removed = new Segment[hi - lo];
            for (int i = lo; i < hi; i++) {
                removed[i - lo] = segments.get(i);
            }
            final int at = lo;
            journal.push(
                    () -> {
                        segments.subList(at, at + 1).clear();
                        if (removed.length > 0) {
                            segments.addAll(at, Arrays.asList(removed));
                        }
                    });
            segments.subList(lo, hi).clear();
            segments.add(lo, new Segment(mergedStart, mergedEnd, merged));
            return true;
        }

        long unique() {
            long total = 0;
            for (Segment segment : segments) {
                total += segment.end - segment.start;
            }
            return total;
        }

        /** Contiguous byte count from offset zero. */
        long prefixLength() {
            if (segments.isEmpty() || segments.get(0).start != 0) {
                return 0;
            }
            long end = segments.get(0).end;
            for (int i = 1; i < segments.size() && segments.get(i).start == end; i++) {
                end = segments.get(i).end;
            }
            return end;
        }

        byte[] prefixBytes(long length) {
            byte[] out = new byte[(int) length];
            int filled = 0;
            for (Segment segment : segments) {
                if (segment.start > filled || filled >= length) {
                    break;
                }
                int take = (int) Math.min(segment.end - segment.start, length - filled);
                System.arraycopy(segment.data, 0, out, filled, take);
                filled += take;
            }
            return out;
        }

        private int firstEndingAtOrAfter(long value) {
            int lo = 0;
            int hi = segments.size();
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (segments.get(mid).end < value) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
            return lo;
        }

        private int firstStartingAfter(long value) {
            int lo = 0;
            int hi = segments.size();
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (segments.get(mid).start <= value) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
            return lo;
        }
    }

    /** Reconstructs the full packet number closest to expected, ties choosing the larger value. */
    static long reconstruct(long raw, int width, long expected) {
        long modulus = 1L << (8 * width);
        long base = raw + Math.floorDiv(expected - raw, modulus) * modulus;
        if (base < 0) {
            return base + modulus;
        }
        long next = base + modulus;
        return (expected - base) < (next - expected) ? base : next;
    }

    /** Smallest packet number width whose low bytes reconstruct pn against expected. */
    static int canonicalWidth(long pn, long expected) {
        for (int width = 1; width < 4; width++) {
            long mask = (1L << (8 * width)) - 1;
            if (reconstruct(pn & mask, width, expected) == pn) {
                return width;
            }
        }
        return 4;
    }

    static MessageDigest sha256() {
        try {
            return MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException error) {
            throw new IllegalStateException(error);
        }
    }

    static String hex(byte[] bytes) {
        char[] digits = "0123456789abcdef".toCharArray();
        char[] out = new char[2 * bytes.length];
        for (int i = 0; i < bytes.length; i++) {
            int value = bytes[i] & 255;
            out[2 * i] = digits[value >>> 4];
            out[2 * i + 1] = digits[value & 15];
        }
        return new String(out);
    }

    static byte[] unhex(String text) {
        byte[] out = new byte[text.length() / 2];
        for (int i = 0; i < out.length; i++) {
            out[i] = (byte) ((Character.digit(text.charAt(2 * i), 16) << 4) | Character.digit(text.charAt(2 * i + 1), 16));
        }
        return out;
    }
}
